changeSet.sql:
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pg_trgm;

changeSet.rollback:
DROP EXTENSION IF EXISTS pg_trgm;
DROP EXTENSION IF EXISTS "uuid-ossp";
DROP EXTENSION IF EXISTS vector;

changeSet.createProcedure:
CREATE OR REPLACE FUNCTION create_vector_table(dimension INTEGER)
RETURNS TEXT AS $$
DECLARE
    v_table_name TEXT;
BEGIN
    v_table_name := 'ai_vector_store_' || dimension::TEXT;
    IF EXISTS (SELECT 1 FROM information_schema.tables t WHERE t.table_name = v_table_name) THEN
        RETURN v_table_name || ' already exists';
    END IF;

    IF dimension <= 2000 THEN
        EXECUTE format('
            CREATE TABLE %I (
                id BIGSERIAL PRIMARY KEY,
                vector_id VARCHAR(100) UNIQUE NOT NULL,
                kb_id VARCHAR(64) NOT NULL,
                document_id VARCHAR(64),
                chunk_id VARCHAR(64),
                collection_name VARCHAR(100) NOT NULL,
                embedding vector(%s) NOT NULL,
                content TEXT NOT NULL,
                metadata JSONB,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (kb_id) REFERENCES ai_knowledge_base(id) ON DELETE CASCADE,
                FOREIGN KEY (document_id) REFERENCES ai_document(id) ON DELETE CASCADE,
                FOREIGN KEY (chunk_id) REFERENCES ai_document_chunk(id) ON DELETE CASCADE
            );
            CREATE INDEX idx_%I_kb_id ON %I (kb_id);
            CREATE INDEX idx_%I_embedding ON %I USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);
            CREATE INDEX idx_%I_content_trgm ON %I USING gist (content gist_trgm_ops);
        ', v_table_name, dimension, v_table_name, v_table_name, v_table_name, v_table_name, v_table_name, v_table_name);
    ELSIF dimension <= 4000 THEN
        EXECUTE format('
            CREATE TABLE %I (
                id BIGSERIAL PRIMARY KEY,
                vector_id VARCHAR(100) UNIQUE NOT NULL,
                kb_id VARCHAR(64) NOT NULL,
                document_id VARCHAR(64),
                chunk_id VARCHAR(64),
                collection_name VARCHAR(100) NOT NULL,
                embedding halfvec(%s) NOT NULL,
                content TEXT NOT NULL,
                metadata JSONB,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (kb_id) REFERENCES ai_knowledge_base(id) ON DELETE CASCADE,
                FOREIGN KEY (document_id) REFERENCES ai_document(id) ON DELETE CASCADE,
                FOREIGN KEY (chunk_id) REFERENCES ai_document_chunk(id) ON DELETE CASCADE
            );
            CREATE INDEX idx_%I_kb_id ON %I (kb_id);
            CREATE INDEX idx_%I_embedding ON %I USING hnsw (embedding halfvec_cosine_ops);
            CREATE INDEX idx_%I_content_trgm ON %I USING gist (content gist_trgm_ops);
        ', v_table_name, dimension, v_table_name, v_table_name, v_table_name, v_table_name, v_table_name, v_table_name);
    ELSE
        EXECUTE format('
            CREATE TABLE %I (
                id BIGSERIAL PRIMARY KEY,
                vector_id VARCHAR(100) UNIQUE NOT NULL,
                kb_id VARCHAR(64) NOT NULL,
                document_id VARCHAR(64),
                chunk_id VARCHAR(64),
                collection_name VARCHAR(100) NOT NULL,
                embedding vector(%s) NOT NULL,
                content TEXT NOT NULL,
                metadata JSONB,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (kb_id) REFERENCES ai_knowledge_base(id) ON DELETE CASCADE,
                FOREIGN KEY (document_id) REFERENCES ai_document(id) ON DELETE CASCADE,
                FOREIGN KEY (chunk_id) REFERENCES ai_document_chunk(id) ON DELETE CASCADE
            );
            CREATE INDEX idx_%I_kb_id ON %I (kb_id);
            CREATE INDEX idx_%I_content_trgm ON %I USING gist (content gist_trgm_ops);
        ', v_table_name, dimension, v_table_name, v_table_name, v_table_name, v_table_name);
    END IF;
    RETURN v_table_name || ' created successfully';
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
SELECT create_vector_table(768);
SELECT create_vector_table(1536);
SELECT create_vector_table(2048);
SELECT create_vector_table(4096);
